const PADDING = 50;
const COORDINATE_MAX = 2160;
const CANVAS_SIZE = Math.min(SCREEN_WIDTH, SCREEN_HEIGHT) - PADDING * 2;

const App = () => {
  const [allPoints, setAllPoints] = useState([]);
  const [batchIndex, setBatchIndex] = useState(0);
  const [nextPointToHit, setNextPointToHit] = useState(0);
  const [completedPaths, setCompletedPaths] = useState([]);
  const [currentPath, setCurrentPath] = useState('');
  const [isFinished, setIsFinished] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // 1. API Call with Error Handling and Validation
  const fetchPoints = async () => {
    setIsLoading(true);
    setError(null);
    try {
      // Simulating API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      const mockData = Array.from({ length: 30 }, () => ({
        x: Math.floor(Math.random() * COORDINATE_MAX),
        y: Math.floor(Math.random() * COORDINATE_MAX),
      }));

      if (!Array.isArray(mockData) || mockData.length === 0) {
        throw new Error("Invalid or empty data received from server.");
      }

      setAllPoints(mockData);
    } catch (err) {
      setError("Failed to load points. Please check your connection.");
      Alert.alert("Error", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchPoints();
  }, []);

  // 2. Robust Coordinate Scaling
  const scale = (val) => {
    if (typeof val !== 'number' || isNaN(val)) return 0;
    return (val / COORDINATE_MAX) * CANVAS_SIZE + PADDING;
  };

  const currentBatch = allPoints.slice(batchIndex * 10, (batchIndex + 1) * 10);

  // 3. User Interaction with Safety Checks
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        const { locationX, locationY } = evt.nativeEvent;
        if (isNaN(locationX) || isNaN(locationY)) return;
        setCurrentPath(`M${locationX},${locationY}`);
      },
      onPanResponderMove: (evt) => {
        const { locationX, locationY } = evt.nativeEvent;
        if (isNaN(locationX) || isNaN(locationY)) return;

        setCurrentPath((prev) => `${prev} L${locationX},${locationY}`);

        if (!isFinished && currentBatch.length > 0 && nextPointToHit < currentBatch.length) {
          const target = currentBatch[nextPointToHit];

          if (target && typeof target.x === 'number' && typeof target.y === 'number') {
            const sx = scale(target.x);
            const sy = scale(target.y);
            const distance = Math.sqrt(Math.pow(locationX - sx, 2) + Math.pow(locationY - sy, 2));

            if (distance < 35) {
              const nextIdx = nextPointToHit + 1;
              setNextPointToHit(nextIdx);

              if (nextIdx === 10 || nextIdx === currentBatch.length) {
                handleTransition();
              }
            }
          }
        }
      },
      onPanResponderRelease: () => {
        if (currentPath) {
          setCompletedPaths((prev) => [...prev, currentPath]);
          setCurrentPath('');
        }
      },
      onPanResponderTerminate: () => {
        setCurrentPath(''); // Safety: clear path on hardware interruptions
      }
    })
  ).current;

  const handleTransition = () => {
    const nextBatchStart = (batchIndex + 1) * 10;
    if (nextBatchStart < allPoints.length) {
      setBatchIndex(batchIndex + 1);
      setNextPointToHit(0);
    } else {
      setIsFinished(true);
    }
  };

  if (isLoading) return <View style={styles.center}><ActivityIndicator size="large" color="#0000ff" /></View>;
  if (error) return (
    <View style={styles.center}>
      <Text style={styles.errorText}>{error}</Text>
      <TouchableOpacity onPress={fetchPoints} style={styles.button}><Text>Retry</Text></TouchableOpacity>
    </View>
  );

  return (
    <View style={styles.container}>
      <Text style={styles.header}>
        {isFinished ? "Drawing Complete!" : `Batch ${batchIndex + 1}: Connect Point ${nextPointToHit + 1}`}
      </Text>

      <View {...panResponder.panHandlers} style={styles.canvas}>
        <Svg width="100%" height="100%" style={StyleSheet.absoluteFill}>
          {completedPaths.map((path, i) => (
            <Path key={`path-${i}`} d={path} stroke="black" strokeWidth="3" fill="none" />
          ))}

          {currentPath ? <Path d={currentPath} stroke="blue" strokeWidth="3" fill="none" /> : null}

          {!isFinished && currentBatch.map((pt, index) => {
            const sx = scale(pt.x);
            const sy = scale(pt.y);
            const isActive = index === nextPointToHit;
            const isDone = index < nextPointToHit;

            return (
              <G key={`pt-${batchIndex}-${index}`}>
                <Circle 
                  cx={sx} cy={sy} r={isActive ? 15 : 10} 
                  fill={isDone ? "#4CAF50" : (isActive ? "#2196F3" : "#F44336")} 
                />
                <SvgText x={sx} y={sy + 5} fontSize="10" fill="white" textAnchor="middle" fontWeight="bold">
                  {index + 1}
                </SvgText>
              </G>
            );
          })}
        </Svg>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#f8f9fa' },
  center: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: 20 },
  header: { marginTop: 60, textAlign: 'center', fontSize: 18, fontWeight: 'bold', color: '#333' },
  canvas: { flex: 1, marginTop: 20, backgroundColor: 'white' },
  button: { marginTop: 20, paddingHorizontal: 30, paddingVertical: 12, backgroundColor: '#2196F3', borderRadius: 25 },
  errorText: { color: '#D32F2F', textAlign: 'center', marginBottom: 10 }
});

export default App;
```

### Key Logic Explanations:

1.  **Point Erasure**: The points are rendered using `currentBatch.map(...)`. Because `currentBatch` is a slice of the `allPoints` array based on the `batchIndex`, as soon as `setBatchIndex` is called, the component re-renders with a completely new set of points. The old ones are no longer in the array and disappear.
2.  **Curve Retention**: User drawings are saved to `completedPaths` during `onPanResponderRelease`. This array is never cleared, ensuring all user strokes remain visible.
3.  **Final State**: When `isFinished` is set to `true`, the conditional rendering block removes the final set of points, leaving only the user-drawn curves.
4.  **Interaction Safety**: We maintain `isNaN` checks and `onPanResponderTerminate` to ensure the app handles hardware glitches or phone call interruptions without crashing or leaving the SVG in an invalid state.

Using the free versions of **Ultimate Member (UM)** and **Meta Box (MB)** for frontend CRUD operations is a common and effective strategy, but it requires more "manual labor" than their Pro counterparts.

As an experienced developer, you should be aware of the following limitations and architectural considerations.

### 1. Limitations & Considerations

*   **No Automatic Frontend Forms:** The free version of Meta Box does not include the "MB Frontend Submission" extension. You must manually write the HTML forms, handle `$_POST` data, and manage security (nonces).
*   **Media Handling:** Handling file uploads (e.g., an Artiste's profile picture or gallery) is significantly more complex manually. You have to use `wp_handle_upload()` and manually associate the attachment ID with the post meta.
*   **Validation:** You lose the built-in PHP/JS validation provided by Meta Box Pro. You must implement your own validation logic to ensure data integrity before calling `update_post_meta`.
*   **UI/UX Consistency:** Since you are injecting custom HTML into a UM tab, you need to manually apply UM's CSS classes (like `um-field`, `um-button`) to make the form look native to the profile.
*   **Performance:** The free version of Meta Box stores data in the standard `wp_postmeta` table. While fine for most sites, if you eventually have tens of thousands of "Artistes" with dozens of fields, queries might slow down compared to the "MB Custom Table" (Pro) extension.

### 2. Best Practices & Enhancements

To simplify and enhance your implementation, I recommend the following:

1.  **Shortcode-Based Rendering:** Instead of putting all HTML in the hook, wrap the form in a shortcode. This makes it easier to test and allows you to place the form on other pages if needed.
2.  **Flash Messages:** Use UM's notice system or a custom session-based notice to tell the user "Profile Updated Successfully."
3.  **Capability Checks:** Don't just check if the user is logged in; check if they have the specific capability to edit their own "Artiste" post.
4.  **Centralized Field Mapping:** Create a helper function that returns an array of your Meta Box fields to avoid DRY (Don't Repeat Yourself) violations when rendering and saving.

### 3. Enhanced Implementation (PHP logic)

Here is a more robust version of the logic, including a basic example of how to handle a **File Upload** (often needed for Artistes) and better feedback. This version also consolidates the **Delete** logic into the main redirect hook to ensure clean execution.

