**Note:** Your server must have the Tesseract binary installed. On Render, you can use a custom Dockerfile or a build script to include it.

```python
import os
import re
import pdfplumber
from PIL import Image
import pytesseract
from flask import Flask, request, jsonify
from flask_cors import CORS
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import openai
from duckduckgo_search import DDGS

app = Flask(__name__)
CORS(app)

# Rate limiting to prevent API abuse
limiter = Limiter(
    get_remote_address,
    app=app,
    default_limits=["100 per day", "10 per hour"],
    storage_uri="memory://",
)

openai.api_key = os.getenv("OPENAI_API_KEY")

def sanitize_input(text):
    """Removes special characters to prevent prompt injection or search errors."""
    return re.sub(r'[^\w\s,]', '', text).strip()

def extract_text_from_pdf(file):
    with pdfplumber.open(file) as pdf:
        return " ".join([page.extract_text() for page in pdf.pages if page.extract_text()])

def extract_text_from_image(file):
    img = Image.open(file)
    return pytesseract.image_to_string(img)

def gather_internet_lore(ingredients):
    lore_context = ""
    try:
        with DDGS() as ddgs:
            for ingredient in ingredients[:2]:
                clean_ing = sanitize_input(ingredient)
                query = f"magical folklore and symbolic meaning of {clean_ing}"
                results = list(ddgs.text(query, max_results=2))

                if results:
                    lore_context += f"\nLore for {ingredient}:\n"
                    for r in results:
                        # Restore HTML sanitization and formatting from Turn 3
                        snippet = re.sub('<[^<]+?>', '', r['body'])
                        lore_context += f"- {snippet}\n"
    except Exception:
        return "No additional folklore found."
    return lore_context

@app.route('/generate-spell', methods=['POST'])
@limiter.limit("5 per minute")
def generate_spell():
    recipe_text = ""

    # 1. Handle File Upload or Text Input
    if 'recipe_file' in request.files:
        file = request.files['recipe_file']
        if file.filename.lower().endswith('.pdf'):
            recipe_text = extract_text_from_pdf(file)
        elif file.filename.lower().endswith(('.png', '.jpg', '.jpeg')):
            recipe_text = extract_text_from_image(file)

    if not recipe_text:
        recipe_text = request.form.get('recipe_text', '')

    if not recipe_text or len(recipe_text) < 10:
        return jsonify({"error": "Could not read recipe. Please upload a clear file or paste text."}), 400

    try:
        # 2. Use AI to extract a clean ingredient list from messy OCR/text
        extraction = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "Extract only the main ingredients from this recipe as a comma-separated list."},
                {"role": "user", "content": recipe_text[:2000]}
            ]
        )
        raw_list = extraction.choices[0].message.content.split(',')
        ingredients = [sanitize_input(i)[:30] for i in raw_list[:5] if len(i.strip()) > 1]

        # 3. Gather Research
        internet_research = gather_internet_lore(ingredients)

        # 4. Generate Structured Spell (Restoring Turn 3 requirements)
        response = openai.ChatCompletion.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a helpful assistant that creates poetic, coherent kitchen spells based on folklore. Ensure the tone is mystical but safe."},
                {"role": "user", "content": f"""
                    Ingredients: {', '.join(ingredients)}
                    Research: {internet_research}

                    Create a spell with:
                    1. Name
                    2. Intent
                    3. Rhyming Incantation
                    4. A 'Folklore Fact' based on the research.
                """}
            ],
            temperature=0.7,
            max_tokens=500
        )

        return jsonify({
            "spell": response.choices[0].message.content, 
            "ingredients": ingredients
        })

    except Exception as e:
        return jsonify({"error": "The mystical energies are unstable. Try again."}), 500

if __name__ == '__main__':
    app.run(debug=False)
```

